operation.query:
SET @ReturnValue = 0;
INSERT INTO [GBVAttachment] ([GBVmainID] ,[Filename] ,[FileAttached] ,[ContentType] ,[CreationUserID] ,[LastModificationTimestamp] ,[LastModificationUserID] ,[Deleted]) VALUES (@GBVMainID ,@Filename ,@FileAttached ,@ContentType ,@CreationUserID ,@LastModificationTimestamp ,@LastModificationUserID ,0);
SET @ReturnValue = SCOPE_IDENTITY();
UPDATE [GBVMain] SET [LastModificationTimestamp] = GETDATE() ,[LastModificationUserID] = @CreationUserID ,[ConsentSigned] = 1 WHERE GBVMainID = @GBVMainID
